const url = "ws://127.0.0.1:19528/";
const socket = new WebSocket(url);
const messages: unknown[] = [];

function shape(value: unknown, depth = 0): unknown {
  if (depth > 4) return "[depth-limit]";
  if (Array.isArray(value)) {
    return {
      kind: "array",
      length: value.length,
      itemShapes: value.slice(0, 3).map((item) => shape(item, depth + 1)),
    };
  }
  if (value && typeof value === "object") {
    const source = value as Record<string, unknown>;
    const result: Record<string, unknown> = { kind: "object", keys: Object.keys(source).sort() };
    for (const [key, item] of Object.entries(source)) {
      if (key === "type" && typeof item === "string") result.type = item;
      else if (typeof item === "boolean" || typeof item === "number" || item === null) result[key] = item;
      else if (Array.isArray(item) || (item && typeof item === "object")) result[key] = shape(item, depth + 1);
      else if (typeof item === "string") result[key] = `[string:${item.length}]`;
    }
    return result;
  }
  return `[${typeof value}]`;
}

const done = new Promise<void>((resolve, reject) => {
  const timer = setTimeout(() => {
    socket.close();
    resolve();
  }, 4_000);

  const sendProbes = () => {
    const requests = [
      { type: "ping" },
      { type: "request.get_accounts" },
      { type: "request.get_current_account" },
      { type: "request.get_accounts", payload: {} },
      { type: "request.get_accounts", payload: { platform: "cursor" } },
      { type: "request.get_current_account", payload: { platform: "cursor" } },
      { id: "probe-accounts", type: "request.get_accounts", payload: { platform: "cursor" } },
      { requestId: "probe-current", type: "request.get_current_account", payload: { platform: "cursor" } },
    ];
    requests.forEach((request, index) => {
      setTimeout(() => socket.send(JSON.stringify(request)), 150 + index * 300);
    });
  };
  let probesSent = false;
  socket.addEventListener("message", (event) => {
    try {
      const parsed = JSON.parse(String(event.data));
      messages.push(shape(parsed));
      if (!probesSent && parsed?.type === "event.ready") {
        probesSent = true;
        sendProbes();
      }
    } catch {
      messages.push({ kind: "non-json", bytes: String(event.data).length });
    }
  });
