type Credential = {
  access: string;
  refresh: string;
  expires: number;
  accountId?: string;
  email?: string;
  source?: string;
};

type Account = {
  id: string;
  credential: Credential;
  alias?: string;
  needsReauth?: boolean;
  addedAt?: number;
};

type AccountSet = {
  activeAccountId: string;
  accounts: Account[];
};

function requireAccountSet(value: unknown): AccountSet {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("cursor must be an object");
  }
  const candidate = value as Partial<AccountSet>;
  if (typeof candidate.activeAccountId !== "string" || !candidate.activeAccountId) {
    throw new Error("cursor.activeAccountId must be a non-empty string");
  }
  if (!Array.isArray(candidate.accounts) || candidate.accounts.length === 0) {
    throw new Error("cursor.accounts must contain at least one account");
  }
  for (const [index, account] of candidate.accounts.entries()) {
    if (!account || typeof account !== "object" || typeof account.id !== "string" || !account.id) {
      throw new Error(`cursor.accounts[${index}].id must be a non-empty string`);
    }
    const credential = account.credential;
    if (!credential || typeof credential !== "object") {
      throw new Error(`cursor.accounts[${index}].credential must be an object`);
    }
    if (typeof credential.access !== "string" || !credential.access) {
      throw new Error(`cursor.accounts[${index}].credential.access is missing`);
    }
    if (typeof credential.refresh !== "string" || !credential.refresh) {
      throw new Error(`cursor.accounts[${index}].credential.refresh is missing`);
    }
    if (typeof credential.expires !== "number" || !Number.isFinite(credential.expires)) {
      throw new Error(`cursor.accounts[${index}].credential.expires must be a finite number`);
    }
  }
  if (!candidate.accounts.some((account) => account.id === candidate.activeAccountId)) {
    throw new Error("cursor.activeAccountId does not identify an account");
  }
  return candidate as AccountSet;
}

