function readVarint(buffer: Buffer, start: number): { value: number; next: number } {
  let value = 0;
  let shift = 0;
  let position = start;
  while (position < buffer.length && shift <= 28) {
    const byte = buffer[position++]!;
    value |= (byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) return { value: value >>> 0, next: position };
    shift += 7;
  }
  throw new Error("Invalid LevelDB varint");
}

function logicalRecords(log: Buffer): Buffer[] {
  const records: Buffer[] = [];
  let fragmented: Buffer[] = [];
  const blockSize = 32_768;
  for (let blockStart = 0; blockStart < log.length; blockStart += blockSize) {
    const blockEnd = Math.min(blockStart + blockSize, log.length);
    let position = blockStart;
    while (position + 7 <= blockEnd) {
      const length = log.readUInt16LE(position + 4);
      const type = log[position + 6]!;
      position += 7;
      if (length === 0 && type === 0) break;
      if (position + length > blockEnd) break;
      const payload = log.subarray(position, position + length);
      position += length;
      if (type === 1) records.push(Buffer.from(payload));
      else if (type === 2) fragmented = [Buffer.from(payload)];
      else if (type === 3 && fragmented.length) fragmented.push(Buffer.from(payload));
      else if (type === 4 && fragmented.length) {
        fragmented.push(Buffer.from(payload));
        records.push(Buffer.concat(fragmented));
        fragmented = [];
      }
    }
  }
  return records;
}

function valuesForKey(log: Buffer, wantedKey: string): Buffer[] {
  const values: Buffer[] = [];
  for (const record of logicalRecords(log)) {
    if (record.length < 12) continue;
    const count = record.readUInt32LE(8);
    let position = 12;
    for (let index = 0; index < count && position < record.length; index++) {
      const tag = record[position++]!;
      const keyLength = readVarint(record, position);
      position = keyLength.next;
      const key = record.subarray(position, position + keyLength.value);
      position += keyLength.value;
      if (tag === 0) continue;
      if (tag !== 1) throw new Error(`Unsupported LevelDB write tag ${tag}`);
      const valueLength = readVarint(record, position);
      position = valueLength.next;
      const value = record.subarray(position, position + valueLength.value);
      position += valueLength.value;
      const keyText = `${key.toString("utf8")}\n${key.toString("utf16le")}`;
      if (keyText.includes(wantedKey)) values.push(Buffer.from(value));
    }
  }
  return values;
}

function decodeJson(value: Buffer): unknown | undefined {
  const byteSlices = [value, value.subarray(Math.min(1, value.length)), value.subarray(Math.min(2, value.length))];
  for (const bytes of byteSlices) {
    for (const encoding of ["utf8", "utf16le"] as const) {
      let text = bytes.toString(encoding).replace(/^\uFEFF/, "").replace(/\0+$/g, "").trim();
      for (let depth = 0; depth < 3; depth++) {
        try {
          const parsed = JSON.parse(text);
          if (typeof parsed === "string") {
            text = parsed;
            continue;
          }
          return parsed;
        } catch {
          break;
        }
      }
    }
  }
  return undefined;
}

function findAccounts(value: unknown): ForgeCursorAccount[] {
  if (Array.isArray(value)) {
    if (value.some((item) => item && typeof item === "object" && "access_token" in item)) {
      return value as ForgeCursorAccount[];
    }
    for (const item of value) {
      const nested = findAccounts(item);
      if (nested.length) return nested;
    }
  } else if (value && typeof value === "object") {
    for (const item of Object.values(value as Record<string, unknown>)) {
      const nested = findAccounts(item);
      if (nested.length) return nested;
    }
  }
  return [];
}

